using System.Threading.Tasks;using UnityEngine; [CreateAssetMenu(menuName="Under The Horizon/Interaction Actions/Puzzle")] public sealed class PuzzleInteractionAction:InteractionAction { [SerializeField]private PuzzleDefinition puzzle;public override async Task<InteractionResult> ExecuteAsync(InteractionContext context){if(context.Puzzles==null)return new(false);PuzzleResult result=await context.Puzzles.PlayAsync(puzzle,context.State);return new InteractionResult(result.Completed);} }
